insert into demo_seed.shop_tpl values ('kitchen','FOOD','Restaurant','Home-style South Indian and Coorg meals, cooked fresh every day. Dine in or order for delivery.','11am to 10:30pm',6,false),('bakery','FOOD','Bakery','Breads, cakes and snacks baked every morning. Custom birthday cakes on request.','7am to 9pm',8,false),('grocery','GROCERY','Grocery','Daily groceries, staples and Coorg coffee at fair prices. Home delivery within 5 km.','7am to 10pm',8,true),('veggies','VEGETABLES','Vegetables','Farm-fresh vegetables and fruit, picked this morning.','6am to 8pm',8,true),('meat','MEAT','Meat and fish','Hygienically cut chicken, mutton and fresh fish. Cleaned and packed on order.','7am to 8:30pm',8,false),('fashion','SHOPPING','Clothing','Everyday and festive wear for the family. Easy exchange within 7 days.','10am to 9pm',8,false),('gadgets','SHOPPING','Electronics','Phones, audio and accessories with a one-year warranty on every item.','10am to 9pm',8,false),('stationers','SHOPPING','Stationery','School and office stationery, gift items and art supplies.','9am to 8pm',8,false),('pharmacy','SHOPPING','Pharmacy','Medicines, health products and baby care. Prescription items need a valid prescription.','8am to 11pm',8,false),('decor','SHOPPING','Home decor','Planters, lamps and handmade decor to make a house feel like home.','10am to 8:30pm',8,false);
